    cells = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value != 0]
    if not cells:
        return [row[:] for row in grid]
    bottom = max(r for r, _ in cells)
    out = [[0] * len(grid[0]) for _ in grid]
    for r, c in cells:
